  }
  .progress li {
    padding: 8px 2px;
    text-align: center;
    border-bottom: 3px solid var(--muted);
  }
  .progress [aria-current="step"] {
    font-weight: 750;
    border-color: var(--ink);
    background: var(--primary);
    border-radius: 6px 6px 0 0;
  }
  fieldset { border: 0; padding: 0; margin: 0; min-width: 0; }
  legend { font-weight: 650; margin-bottom: 12px; padding: 0; }
  .options { display: grid; gap: 12px; }
  .choice {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    min-height: 56px;
    padding: 14px 12px;
    border: 1px solid var(--muted);
    border-radius: var(--radius);
    cursor: pointer;
  }
  .choice:has(input:checked) {
    border: 2px solid var(--ink);
    padding: 13px 11px;
    background: #EFFAF5;
  }
  .choice input {
    width: 20px;
    height: 20px;
    flex: 0 0 20px;
    margin: 3px 0 0;
    accent-color: var(--ink);
  }
  .choice strong, .choice .meta { display: block; }
  button, a, input { touch-action: manipulation; }
  button {
    min-height: 48px;
    padding: 12px;
    border: 1px solid var(--ink);
    border-radius: var(--radius);
    background: var(--surface);
    color: var(--ink);
    font: inherit;
    font-weight: 650;
    cursor: pointer;
  }
  button.primary {
    background: var(--primary);
    color: var(--action-text);
  }
  button:disabled { opacity: .55; cursor: not-allowed; }
  :focus-visible {
    outline: 3px solid var(--ink);
    outline-offset: 4px;
  }
  .actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin: 20px 0;
  }
  .actions button { flex: 1 1 120px; }
  aside {
    border: 1px solid var(--muted);
    border-radius: var(--radius);
    padding: 16px;
    margin-top: 24px;
  }
  dl { margin: 0; }
  dl > div { margin-top: 10px; }
  dt { color: var(--muted); font-size: .875rem; }
  dd { margin: 0; font-weight: 600; }
  .review dl {
    padding: 16px;
    border: 1px solid var(--muted);
    border-radius: var(--radius);
  }
  .error {
    padding: 12px;
    border: 2px solid var(--ink);
    border-radius: var(--radius);
    font-weight: 650;
  }
  .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
