    white-space: nowrap;
    border: 0;
  }
</style>
</head>
<body>
<main>
  <header>
    <p class="brand">पेटसाथी</p>
    <h1>अपॉइंटमेंट बुक करें</h1>
    <p>गुलमोहर मार्ग क्लिनिक<br>
      <span class="meta">12, गुलमोहर मार्ग, उदाहरणपुर</span>
    </p>
    <p class="note">
      <strong>इंटरैक्टिव डेमो</strong><br>
      गुरुवार, 16 जुलाई 2026 केवल उदाहरण की तारीख है।
      कोई वास्तविक बुकिंग या भुगतान नहीं होगा।
    </p>
  </header>

  <nav aria-label="बुकिंग की प्रगति">
    <ol class="progress">
      <li aria-current="step">1. सेवा</li>
      <li>2. डॉक्टर</li>
      <li>3. समय</li>
      <li>4. पुष्टि</li>
    </ol>
  </nav>

  <section data-step="0" aria-labelledby="title-0">
    <h2 id="title-0" tabindex="-1">1. सेवा चुनें</h2>
    <fieldset>
      <legend>किस सेवा के लिए आना है?</legend>
      <div id="services" class="options"></div>
    </fieldset>
  </section>

  <section data-step="1" aria-labelledby="title-1" hidden>
    <h2 id="title-1" tabindex="-1">2. डॉक्टर चुनें</h2>
    <p id="doctor-help"></p>
    <fieldset aria-describedby="doctor-help">
      <legend>आपकी पसंद</legend>
      <div id="doctors" class="options"></div>
    </fieldset>
  </section>

  <section data-step="2" aria-labelledby="title-2" hidden>
    <h2 id="title-2" tabindex="-1">3. समय चुनें</h2>
    <p><strong>गुरुवार, 16 जुलाई 2026 — डेमो</strong><br>
      <span class="meta">
        समय क्लिनिक के स्थानीय समय में है।<br>
        खुला: 09:00–13:00 और 14:00–17:00
      </span>
    </p>
    <fieldset id="time-field">
      <legend>उपलब्ध समय और डॉक्टर</legend>
      <div id="slots" class="options"></div>
    </fieldset>
    <div id="empty" class="empty" hidden>
      <strong>इस चयन के लिए उपलब्ध समय नहीं मिला।</strong>
      <p>इस डेमो में केवल गुरुवार का डेटा है।
        डॉक्टर या सेवा बदलकर देखें।</p>
      <button id="change-doctor" type="button">डॉक्टर बदलें</button>
      <button id="change-service" type="button">सेवा बदलें</button>
    </div>
  </section>

  <section data-step="3" class="review" aria-labelledby="title-3" hidden>
    <h2 id="title-3" tabindex="-1">4. बुकिंग की पुष्टि करें</h2>
    <p id="review-message">सेवा, डॉक्टर, समय और कीमत जाँच लें।</p>
    <div id="review-details"></div>
    <p class="meta">यह डेमो है; पुष्टि क्लिनिक को नहीं भेजी जाएगी।</p>
  </section>

  <p id="error" class="error" role="alert" hidden></p>

  <div class="actions">
    <button id="back" type="button" hidden>पीछे</button>
    <button id="next" class="primary" type="button" disabled>आगे: डॉक्टर</button>
    <button id="restart" type="button" hidden>नई डेमो बुकिंग</button>
  </div>

  <aside id="summary" aria-labelledby="summary-title">
    <h2 id="summary-title">बुकिंग सारांश</h2>
    <div id="summary-details"></div>
  </aside>

  <div id="announce" class="sr-only" role="status" aria-atomic="true"></div>
</main>

<script>
const services = [
  { id: "wellness", api: "Wellness exam", name: "वेलनेस जाँच",
    duration: 30, price: "₹600", fixed: true, vets: ["mary", "richard"] },
  { id: "vaccine", api: "Vaccination visit", name: "टीकाकरण विज़िट",
    duration: 15, price: "₹400", fixed: true, vets: ["mary", "richard"] },
  { id: "dental", api: "Dental cleaning", name: "दाँतों की सफ़ाई",
    duration: 90, price: "₹3,500 से", fixed: false, vets: ["mary"] },
  { id: "exotic", api: "Exotic pet check-up", name: "एक्ज़ॉटिक पेट जाँच",
    duration: 45, price: "₹900", fixed: true, vets: ["mary"] }
];

const vets = [
  { id: "mary", api: "Mary Major", name: "डॉ. मैरी मेजर",
    days: [2, 4, 6], label: "मंगलवार, गुरुवार, शनिवार" },
  { id: "richard", api: "Richard Miles", name: "डॉ. रिचर्ड माइल्स",
    days: [1, 2, 3, 4, 5, 6], label: "सोमवार–शनिवार" }
];

const apiSlots = [
  {"vet":"Richard Miles","service":"Exotic pet check-up","start":"10:00"},
  {"vet":"Mary Major","service":"Exotic pet check-up","start":"11:00"},
  {"vet":"Mary Major","service":"Dental cleaning","start":"12:00"},
  {"vet":"Richard Miles","service":"Wellness exam","start":"13:30"},
  {"vet":"Richard Miles","service":"Wellness exam","start":"15:00"},
  {"vet":"Mary Major","service":"Wellness exam","start":"16:45"}
];

// यह तारीख API से नहीं मिली है; केवल स्पष्ट रूप से चिह्नित डेमो संदर्भ।
const dateLabel = "गुरुवार, 16 जुलाई 2026 (डेमो)";
const weekday = 4;
const address = "12, गुलमोहर मार्ग, उदाहरणपुर";
const openWindows = [[9 * 60, 13 * 60], [14 * 60, 17 * 60]];
const $ = id => document.getElementById(id);
const state = { step: 0, service: "", vet: "any", slot: "", done: false };

function minutes(time) {
  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) return NaN;
  const [h, m] = time.split(":").map(Number);
  return h * 60 + m;
}
function clock(n) {
  return String(Math.floor(n / 60)).padStart(2, "0") + ":" +
         String(n % 60).padStart(2, "0");
}

// पूरे अपॉइंटमेंट की अवधि एक खुले अंतराल के भीतर होनी चाहिए।
function validate(raw, index) {
  const service = services.find(s => s.api === raw.service);
  const vet = vets.find(v => v.api === raw.vet);
  const start = minutes(raw.start);
  if (!service || !vet || !Number.isFinite(start)) return null;
  if (!service.vets.includes(vet.id) || !vet.days.includes(weekday))
    return null;
  const end = start + service.duration;
  if (!openWindows.some(([a, b]) => start >= a && end <= b))
    return null;
  return {
    id: String(index), service: service.id, vet: vet.id,
    start, end, time: raw.start
  };
}

const seen = new Set();
const validSlots = apiSlots.map(validate).filter(slot => {
  if (!slot) return false;
  const key = `${slot.service}|${slot.vet}|${slot.start}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
}).sort((a, b) => a.start - b.start);

const currentService = () => services.find(s => s.id === state.service);
const currentSlot = () => validSlots.find(s => s.id === state.slot);
const vetName = id => vets.find(v => v.id === id)?.name || "—";
function matchingSlots() {
  return validSlots.filter(s =>
    s.service === state.service &&
    (state.vet === "any" || s.vet === state.vet)
  );
}

// Native radios: टैब, ऐरो-की और स्क्रीन रीडर का मानक व्यवहार।
function option(group, value, title, detail, checked, onChange) {
  const label = document.createElement("label");
  label.className = "choice";
  const input = document.createElement("input");
  input.type = "radio";
  input.name = group;
  input.value = value;
  input.checked = checked;
  input.addEventListener("change", () => onChange(value));

  const text = document.createElement("span");
  const strong = document.createElement("strong");
  strong.textContent = title;
  const meta = document.createElement("span");
  meta.className = "meta";
  meta.textContent = detail;
  text.append(strong, meta);
  label.append(input, text);
  return label;
}

function renderServices() {
  $("services").replaceChildren(...services.map(s => option(
    "service", s.id, s.name,
    `${s.duration} मिनट · ${s.price}` +
    (!s.fixed ? " · अंतिम कीमत पहले तय करना ज़रूरी है" : ""),
    state.service === s.id,
    id => {
      state.service = id;
      state.vet = "any";
      state.slot = "";
      renderDoctors();
      renderSlots();
      update(`सेवा चुनी: ${currentService().name}, ${currentService().price}।
        डॉक्टर और समय का चयन रीसेट हुआ।`);
    }
  )));
}

function renderDoctors() {
  const s = currentService();
  if (!s) { $("doctors").replaceChildren(); return; }
  const eligible = vets.filter(v => s.vets.includes(v.id));
  $("doctor-help").textContent = eligible.length === 1
    ? "इस सेवा के लिए केवल डॉ. मैरी मेजर योग्य हैं। ‘कोई भी’ में भी वही शामिल हैं।"
    : "‘कोई भी उपलब्ध डॉक्टर’ पहले से चुना है। चाहें तो किसी डॉक्टर को चुनें।";
  const choose = id => {
    state.vet = id;
    state.slot = "";
    renderSlots();
    update("डॉक्टर की पसंद बदली। कृपया समय फिर चुनें।");
  };
  $("doctors").replaceChildren(
    option("vet", "any", "कोई भी उपलब्ध डॉक्टर",
      "चुने हुए समय पर डॉक्टर का नाम दिखेगा।",
      state.vet === "any", choose),
    ...eligible.map(v => option("vet", v.id, v.name, v.label,
      state.vet === v.id, choose))
  );
}

function renderSlots() {
  const slots = matchingSlots();
  $("time-field").hidden = !slots.length;
  $("empty").hidden = !!slots.length;
  $("slots").replaceChildren(...slots.map(s => option(
    "slot", s.id, `${s.time}–${clock(s.end)}`, vetName(s.vet),
    state.slot === s.id,
    id => {
      state.slot = id;
      const slot = currentSlot();
      update(`समय चुना: ${slot.time} से ${clock(slot.end)}।
        डॉक्टर: ${vetName(slot.vet)}।`);
    }
  )));
}

function details() {
  const s = currentService(), slot = currentSlot();
  const doctor = slot ? vetName(slot.vet) :
    !s ? "सेवा चुनने के बाद" :
    state.vet === "any" ? "कोई भी उपलब्ध डॉक्टर — समय चुनने पर तय होगा" :
    vetName(state.vet);
  return [
    ["सेवा", s ? `${s.name} · ${s.duration} मिनट` : "अभी नहीं चुनी"],
    ["डॉक्टर", doctor],
    ["तारीख", dateLabel],
    ["समय", slot ? `${slot.time}–${clock(slot.end)}` : "अभी नहीं चुना"],
    ["कीमत", !s ? "सेवा चुनने पर दिखेगी" :
      s.fixed ? `${s.price} · सूचीबद्ध सेवा शुल्क` :
      `${s.price} · अंतिम कुल कीमत अभी उपलब्ध नहीं; पुष्टि रुकेगी`],
    ["क्लिनिक", `गुलमोहर मार्ग क्लिनिक — ${address}`]
  ];
}
function renderDetails(target) {
  const dl = document.createElement("dl");
  for (const [key, value] of details()) {
    const row = document.createElement("div");
    const dt = document.createElement("dt");
    const dd = document.createElement("dd");
    dt.textContent = key;
    dd.textContent = value;
    row.append(dt, dd);
    dl.append(row);
  }
  target.replaceChildren(dl);
}

function canAdvance() {
  const s = currentService(), slot = currentSlot();
  if (state.step === 0) return !!s;
  if (state.step === 1)
    return !!s && (state.vet === "any" || s.vets.includes(state.vet));
  const validSelection = !!slot && matchingSlots().some(x => x.id === slot.id);
  if (state.step === 2) return validSelection;
  return validSelection && !!s?.fixed && !state.done;
}

function update(message = "") {
  document.querySelectorAll("[data-step]").forEach(section => {
    section.hidden = Number(section.dataset.step) !== state.step;
  });
  document.querySelectorAll(".progress li").forEach((li, i) => {
    if (i === state.step) li.setAttribute("aria-current", "step");
    else li.removeAttribute("aria-current");
  });
  $("back").hidden = state.step === 0 || state.done;
  $("next").hidden = state.done;
  $("restart").hidden = !state.done;
  $("next").textContent = [
    "आगे: डॉक्टर", "आगे: समय", "आगे: समीक्षा", "डेमो पुष्टि करें"
  ][state.step];
  $("next").disabled = !canAdvance();
  $("summary").hidden = state.step === 3;
  renderDetails($("summary-details"));
  renderDetails($("review-details"));
  if (message) $("announce").textContent = message;
}
function go(step) {
  state.step = step;
  $("error").hidden = true;
  if (step === 2) renderSlots();
  update();
  $(`title-${step}`).focus();
}

$("next").addEventListener("click", () => {
  if (!canAdvance()) return;
  if (state.step < 3) { go(state.step + 1); return; }

  // केवल स्थानीय पुनःजाँच। प्रोडक्शन में atomic server validation ज़रूरी है।
  const slot = currentSlot();
  const rechecked = slot && validate(apiSlots[Number(slot.id)], Number(slot.id));
  if (!rechecked || !matchingSlots().some(s => s.id === slot.id)) {
    state.slot = "";
    go(2);
    $("error").textContent = "यह समय अब उपलब्ध नहीं है। दूसरा समय चुनें।";
    $("error").hidden = false;
    return;
  }
  state.done = true;
  $("title-3").textContent = "डेमो बुकिंग की पुष्टि";
  $("review-message").textContent =
    "नीचे आपका पूरा चयन है। वास्तविक अपॉइंटमेंट बुक नहीं हुआ है।";
  update("डेमो पूरा हुआ। कोई वास्तविक बुकिंग नहीं की गई।");
  $("title-3").focus();
});

$("back").addEventListener("click", () => go(state.step - 1));
$("change-doctor").addEventListener("click", () => go(1));
$("change-service").addEventListener("click", () => go(0));
$("restart").addEventListener("click", () => {
  Object.assign(state, {
    step: 0, service: "", vet: "any", slot: "", done: false
  });
  $("title-3").textContent = "4. बुकिंग की पुष्टि करें";
  $("review-message").textContent = "सेवा, डॉक्टर, समय और कीमत जाँच लें।";
  renderServices();
  renderDoctors();
  renderSlots();
  go(0);
});

renderServices();
renderSlots();
update();
</script>
</body>
</html>
```

## 2. डिज़ाइन rationale

### अलग-अलग स्टेप्स क्यों

375 px पर **चार छोटे स्टेप्स** रखे हैं। एक लंबी progressive स्क्रीन में सेवा, डॉक्टर और समय के कई विकल्प आने पर सारांश तथा अगला कार्य स्क्रीन से दूर हो सकते हैं। यहाँ हर स्टेप का एक स्पष्ट निर्णय है; प्रगति सूचक और “पीछे” नेविगेशन संदर्भ बनाए रखते हैं।

वेलनेस और टीकाकरण पहले दो विकल्प हैं। सेवा चुनने के बाद **“कोई भी उपलब्ध डॉक्टर” डिफ़ॉल्ट** है, जिससे सामान्य बुकिंग में डॉक्टर पर अतिरिक्त निर्णय नहीं लेना पड़ता। चयन करते ही स्वतः अगले स्टेप पर नहीं जाते—उपयोगकर्ता आगे बढ़ने को नियंत्रित करता है।

सारांश प्रत्येक चयन पर अपडेट होता है। सेवा बदलने पर डॉक्टर की पसंद और समय रीसेट होते हैं; डॉक्टर बदलने पर समय रीसेट होता है। अंतिम समीक्षा और डेमो-पुष्टि में सभी आवश्यक विवरण साथ दिखते हैं। “कोई भी” चुनने पर भी समय चुनते ही वास्तविक डॉक्टर का नाम सामने आता है।

### “₹3,500 से” का व्यवहार

इसे निश्चित ₹3,500 नहीं बनाया गया। सेवा कार्ड और सारांश दोनों बताते हैं कि अंतिम कुल कीमत उपलब्ध नहीं है। **अंतिम कीमत के बिना पुष्टि रोकना** आवश्यक है; वर्तमान डेटा में दाँतों की सफ़ाई का वैध स्लॉट भी नहीं है।

प्रोडक्शन में क्लिनिक से अंतिम, सभी अनिवार्य शुल्कों सहित कीमत लेकर उपयोगकर्ता की सहमति चाहिए। यदि जाँच के बिना यह संभव नहीं है, तो पहले अलग, स्पष्ट मूल्य वाली मूल्यांकन सेवा ऑफ़र की जाए—उसे सफ़ाई की पुष्टि न कहा जाए। सामान्य सेवाओं की दी गई कीमतें यहाँ सूचीबद्ध शुल्क हैं; अतिरिक्त शुल्क नहीं गढ़े गए हैं।

### ब्रांड और WCAG 2.2 AA

`#7FD1AE` पर सफेद लेबल का कंट्रास्ट लगभग **1.8:1** है—सामान्य पाठ के आवश्यक **4.5:1** से कम। इसलिए primary पृष्ठभूमि वही रखी, लेकिन लेबल को `color.ink` किया; इसका कंट्रास्ट लगभग **8:1** है। यह ब्रांड निर्देश से जानबूझकर किया गया विचलन है। बटन की गहरी सीमा उसकी पहचान भी स्पष्ट रखती है।

अन्य निर्णय: 16 px मूल फ़ॉन्ट, कम-से-कम 48 px बटन, पूरे कार्ड पर क्लिक, native radio controls, स्पष्ट keyboard focus, अर्थपूर्ण headings, स्टेप बदलने पर heading focus और चयन की live घोषणा। चयन केवल रंग से नहीं बताया गया है। कोई fixed footer नहीं है जो zoom या छोटे viewport पर सामग्री ढके। रिलीज़ से पहले keyboard, स्क्रीन रीडर, zoom और contrast की वास्तविक जाँच फिर भी आवश्यक होगी।

## 3. डेटा समस्याएँ और समाधान

| समस्या | UI / API का व्यवहार |
|---|---|
| रिचर्ड, एक्ज़ॉटिक जाँच, 10:00 | अयोग्य डॉक्टर; स्लॉट छिपाएँ। API सेवा–डॉक्टर पात्रता लागू करे। |
| मैरी, दाँतों की सफ़ाई, 12:00 | 90 मिनट की सेवा 13:30 तक चलेगी और लंच से टकराएगी; स्लॉट हटाएँ। |
| रिचर्ड, वेलनेस, 13:30 | लंच के दौरान शुरू होता है; स्लॉट हटाएँ। |
| मैरी, वेलनेस, 16:45 | 17:15 पर समाप्त होगा, बंद होने के बाद; स्लॉट हटाएँ। |
| टीकाकरण का कोई स्लॉट नहीं | खाली स्थिति दिखाएँ; वेलनेस स्लॉट को टीकाकरण का स्लॉट मानकर पुनः उपयोग न करें। |
