        }</span>`;
        b.addEventListener("click", () => {
          selectedVet = vet.id; selectedSlot = null;
          box.querySelectorAll("button").forEach(x =>
            x.setAttribute("aria-pressed", String(x === b)));
          $("confirmSection").hidden = true;
          $("confirmMessage").textContent = "";
          renderSlots();
          updateSummary();
        });
        box.append(b);
      });
    }
    function renderSlots() {
      $("slotSection").hidden = false;
      const box = $("slotChoices");
      box.replaceChildren();
      const s = services[selectedService];
      const matches = validSlots.filter(slot =>
        slot.service === s.api &&
        (selectedVet === anyVet || slot.vet === selectedVet)
      );
      $("emptySlots").hidden = matches.length > 0;
      $("emptySlots").textContent = "इस सेवा और डॉक्टर के लिए इस तारीख पर API ने कोई बुक करने योग्य स्लॉट नहीं लौटाया। दूसरी तारीख की उपलब्धता जाँचें।";
      matches.forEach(slot => {
        const vet = vets.find(v => v.id === slot.vet);
        const b = document.createElement("button");
        b.className = "slot"; b.type = "button";
        b.setAttribute("aria-pressed", "false");
        b.setAttribute("aria-label", `${slot.start} बजे, ${vet.name}`);
        b.innerHTML = `<strong>${slot.start}</strong><br><span class="hint">${vet.name}</span>`;
        b.addEventListener("click", () => {
          selectedSlot = slot;
          box.querySelectorAll("button").forEach(x =>
            x.setAttribute("aria-pressed", String(x === b)));
          $("confirmSection").hidden = false;
          $("confirmBtn").disabled = !s.exact;
          $("confirmMessage").textContent = s.exact ? "" : "सटीक अंतिम कीमत के बिना पुष्टि उपलब्ध नहीं है।";
          updateSummary();
        });
        box.append(b);
      });
    }
    $("confirmBtn").addEventListener("click", () => {
      if (!selectedSlot || !services[selectedService].exact) return;
      $("confirmMessage").textContent =
        "डेमो पुष्टि: गुरुवार, 18 जून 2026 · " + selectedSlot.start +
        " · " + vets.find(v => v.id === selectedSlot.vet).name +
        " · " + services[selectedService].name + " · " + services[selectedService].price +
        " · 12, गुलमोहर मार्ग, उदाहरणपुर";
      $("confirmMessage").className = "notice success";
    });
    updateSummary();
  </script>
