      }
    ];

    const money = value => new Intl.NumberFormat("hi-IN", {
      style: "currency",
      currency: "INR",
      minimumFractionDigits: 0,
      maximumFractionDigits: 2
    }).format(value);

    const pricing = document.querySelector("#pricing");
    const grid = document.querySelector("#plans");
    const feedback = document.querySelector("#feedback");
    const radios = [...document.querySelectorAll('input[name="billing"]')];

    let cycle = "annual";
    let loading = false;

    // Internal, static content only. Use safe text bindings for API content.
    const checkIcon = `
      <svg class="check" viewBox="0 0 16 16"
           aria-hidden="true" focusable="false">
        <path d="M2 8l4 4 8-8"
              fill="none" stroke="currentColor" stroke-width="2"
              stroke-linecap="round" stroke-linejoin="round"></path>
      </svg>`;

    function priceVariant(plan, variant) {
      const annual = variant === "annual";
      const amount = annual ? plan.annualDisplay : plan.monthly;
      const bill = annual
        ? `${money(plan.annualBill)} सालाना बिल किया जाएगा (+ GST)`
        : plan.monthly === 0
          ? "मुफ़्त प्लान"
          : `${money(plan.monthly)} मासिक बिल किया जाएगा (+ GST)`;

      return `
        <div class="cycle-copy" data-for="${variant}"
             aria-hidden="${variant !== cycle}">
          <p class="price-line">
            <strong class="amount">${money(amount)}</strong>
            <span class="suffix">
              <span aria-hidden="true">/माह</span>
              <span class="sr-only"> प्रति माह</span>
            </span>
          </p>
          <p class="bill">${bill}</p>
        </div>`;
    }

    grid.innerHTML = plans.map(plan => `
      <article class="card ${plan.id === "pro" ? "recommended" : ""}"
               data-plan="${plan.id}"
               aria-labelledby="${plan.id}-title">
        <header class="card-header">
          <p class="recommendation"
             ${plan.id !== "pro" ? 'aria-hidden="true"' : ""}>
            ${plan.id === "pro" ? "सबसे लोकप्रिय" : ""}
          </p>
          <h2 id="${plan.id}-title">${plan.name}</h2>
        </header>

        <div class="price-stack">
          ${priceVariant(plan, "monthly")}
          ${priceVariant(plan, "annual")}
        </div>

        <ul class="features" role="list">
          ${plan.features.map(feature =>
            `<li>${checkIcon}<span>${feature}</span></li>`
          ).join("")}
        </ul>

        <button class="cta" type="button"
                data-plan="${plan.id}" aria-busy="false"
                aria-label="${plan.cta} — ${plan.name}">
          <span class="loading-mark" aria-hidden="true"></span>
          <span>${plan.cta}</span>
        </button>
      </article>
    `).join("");

    function announcePrices() {
      const heading = cycle === "annual"
        ? "वार्षिक बिलिंग चुनी गई। "
        : "मासिक बिलिंग चुनी गई। ";

      const details = plans.map(plan => {
        if (cycle === "annual") {
          return `${plan.name}: ${money(plan.annualDisplay)} प्रति माह; ` +
                 `${money(plan.annualBill)} सालाना बिल।`;
        }
        return `${plan.name}: ${money(plan.monthly)} प्रति माह।`;
      }).join(" ");

      feedback.textContent = heading + details + " GST अतिरिक्त है।";
    }

    radios.forEach(radio => {
      radio.addEventListener("change", () => {
        if (!radio.checked) return;

        cycle = radio.value;
        pricing.dataset.cycle = cycle;

        radios.forEach(input => {
          input.closest(".segment").dataset.selected =
            String(input.checked);
        });

        document.querySelectorAll(".cycle-copy").forEach(copy => {
          copy.setAttribute(
            "aria-hidden",
            String(copy.dataset.for !== cycle)
          );
        });

        // Focus stays on the radio; no announcement on initial page load.
        announcePrices();
      });
    });

    /*
      Token-derived viewport breakpoint:
      3 × 320px cards + 2 × 16px gaps + 2 × 24px outer padding = 1040px.
      matchMedia avoids introducing an unprovided breakpoint token.
    */
    const styles = getComputedStyle(document.documentElement);
    const px = token => parseFloat(styles.getPropertyValue(token));
    const breakpoint =
      3 * (10 * px("--space-8")) +
      2 * px("--space-4") +
      2 * px("--space-6");

    const wideQuery = matchMedia(`(min-width: ${breakpoint}px)`);

    function applyLayout() {
      const wide = wideQuery.matches;
      const order = wide
        ? ["starter", "pro", "business"]
        : ["pro", "starter", "business"];

      grid.dataset.wide = String(wide);

      // Real DOM order matches visual, reading and keyboard order.
      const active = document.activeElement;
      const restoreFocus = grid.contains(active);

      order.forEach(id => {
        grid.append(grid.querySelector(`.card[data-plan="${id}"]`));
      });

      if (restoreFocus && active.isConnected) {
        active.focus({ preventScroll: true });
      }
    }

    applyLayout();
    wideQuery.addEventListener("change", applyLayout);

    grid.addEventListener("click", async event => {
      const button = event.target.closest("button.cta");
      if (!button || loading) return;

      const plan = plans.find(item => item.id === button.dataset.plan);
      const requestedCycle = cycle; // Snapshot; never read mutable state later.
      const billingLabel = requestedCycle === "annual" ? "वार्षिक" : "मासिक";
      const buttons = [...grid.querySelectorAll(".cta")];

      loading = true;
      buttons.forEach(item => { item.disabled = true; });
      button.setAttribute("aria-busy", "true");
      feedback.textContent = `${plan.name} का चयन तैयार किया जा रहा है।`;

      try {
        // Demo latency only. Replace with the real signup/trial integration.
        await new Promise(resolve => setTimeout(resolve, 800));

        feedback.textContent =
          `${plan.name}, ${billingLabel} बिलिंग चुनी गई। ` +
          "यह डेमो है; कोई ट्रायल, खाता या भुगतान शुरू नहीं हुआ।";
      } catch {
        feedback.textContent =
          "चयन पूरा नहीं हुआ। कृपया दोबारा कोशिश करें।";
      } finally {
        loading = false;
        buttons.forEach(item => { item.disabled = false; });
        button.setAttribute("aria-busy", "false");
        // No focus stealing if the user has moved elsewhere.
      }
    });
  </script>
</body>
</html>
```

## 2. Developer spec

**चिह्न:** `≈` = inspect से बदलाव; `व्युत्पन्न` = मौजूदा टोकनों का गणितीय उपयोग, नया टोकन नहीं।

| Element | Property | Value / टोकन | नोट |
|---|---|---|---|
| टॉगल | प्रकार, विकल्प | Native radio group | मासिक / वार्षिक; वार्षिक डिफ़ॉल्ट |
| टॉगल | ऊँचाई | `--space-8 + --space-2` = 40px | व्युत्पन्न |
| टॉगल | radius | `--radius-full` | ≈ 20px की जगह; 40px ऊँचाई पर वही pill geometry |
| Selected | मूल नीला | `--primary-600` = `#2F6FED` | ≈ inspect `#2F6FEB` को canonical token से बदलें |
| Selected | background/text | primary-600 का 8% transparent मिश्रण / `--primary-700` | ≈ solid blue/`#FFFFFF` नहीं; सफ़ेद टोकन अनुपलब्ध |
| Unselected | text | `--gray-600` | `#4B5563` यथावत |
| वार्षिक badge | copy | “20% बचाएँ” | स्रोतानुसार; रिलीज़ blocker देखें |
| Badge | background/text | primary-600 का 8% मिश्रण / `--primary-700` | ≈ `#E8F7EE`/`#1F7A45` के टोकन नहीं |
| Badge | font size | `--space-3` = 12px | यथावत |
| Card | width | `10 × --space-8` = 320px | छोटे viewport पर उपलब्ध चौड़ाई तक |
| Card | padding | `--space-6` = 24px | यथावत |
| Cards | gap | `--space-4` = 16px | ≈ inspect 14px |
| Card | radius | `--radius-lg` = 12px | यथावत |
| Card | border width/color | `--space-1 / 4` = 1px; gray-500 का 30% मिश्रण | ≈ `#E5E7EB` का exact टोकन नहीं; decorative border |
| Pro | border | `--space-1 / 2` = 2px; `--primary-600` | “सबसे लोकप्रिय” label |
| Price | size/line-height | `--space-8 + --space-2` / `2 × --space-6` = 40/48px | यथावत |
| Price | weight | `<strong>` का platform bold | ≈ semibold का टोकन नहीं; सामान्यतः 700, न कि 600 |
| Suffix | size/color | `--space-4`; `--gray-500` | 16px; `#6B7280`; “/माह” |
| CTA | height/width | `--space-8 + --space-3` = न्यूनतम 44px / 100% | ≈ wrapping/zoom हेतु fixed height नहीं |
| CTA | radius | `--radius-md` = 8px | यथावत |
| CTA | fill/text | transparent / `--primary-700`; primary-600 outline | ≈ blue fill/white text हेतु टोकन अनुपलब्ध |
| Features | size/line-height | `(--space-3 + --space-4)/2` / `--space-5` = 14/20px | व्युत्पन्न |
| Features | icon | `--space-4` = 16px | decorative; text ही अर्थ बताता है |
| Features | row gap | `(--space-2 + --space-3)/2` = 10px | व्युत्पन्न |
| Responsive | breakpoint | `3×320 + 2×16 + 2×24` = 1040px | ≥1040: तीन कॉलम; नीचे Pro, Starter, Business |
| Hover/focus | रंग/outline | `--primary-700`; 2px outline, `--space-1` offset | hover में geometry नहीं बदलती |
| Loading | disabled | Native `disabled`, `aria-busy`; opacity `.55` | सभी CTA बंद; label/आकार स्थिर |

## 3. Accessibility और QA

- **Semantics:** यह billing preference है, tabs/navigation नहीं। `fieldset`/`legend` और समान `name` वाले radios इस्तेमाल हों।
- **Keyboard:** Tab चयनित radio पर आता है; arrow keys native radio चयन बदलती हैं; Space चयन करता है। अगला Tab CTA पर जाता है। कोई custom keyboard interception नहीं।
- **घोषणा:** बदलाव पर एक polite, atomic status बिलिंग अवधि, तीनों कीमतें, वार्षिक totals और GST बताता है। प्रारंभिक लोड पर अनावश्यक घोषणा नहीं। अदृश्य price variant accessibility tree से हटता है।
- **Layout:** दोनों price variants जगह सुरक्षित रखते हैं। Loading icon की जगह भी आरक्षित है। Responsive DOM क्रम दृश्य क्रम से मेल खाता है।
- **Contrast:** सफ़ेद/light canvas पर primary-700 लगभग **6.4:1**, gray-500 **4.8:1**, gray-600 **7.6:1** हैं। हल्के selected tint पर primary-700 भी सामान्य पाठ का 4.5:1 लक्ष्य पार करता है। Selected border/focus primary रंगों में हैं; चयन केवल रंग से नहीं, outline और bold से भी दिखता है। हल्का card border decorative है। Disabled controls contrast exemption में हैं।
- **जाँच:** 1039/1040px, 320px viewport, 200% text zoom, 400% browser zoom, keyboard, VoiceOver/NVDA और forced-colors पर परीक्षण करें। 40px टॉगल न्यूनतम 24px target से बड़ा है; 44px करने पर डिज़ाइन अनुमोदन लें।

## 4. खुले निर्णय

| मुद्दा | सुझाया समाधान / मालिक |
