  </main>

  <script>
    "use strict";

    // INTERACTION DEMO ONLY:
    // No network requests, payment processing, analytics or browser storage.
    // Production must use server-authoritative inventory/expiry, server-side
    // validation, PCI hosted fields and idempotent payment/order endpoints.

    const $ = id => document.getElementById(id);
    const form = $("details");
    const fieldIds = ["name", "email", "card", "exp", "cvc", "captcha"];
    const labels = {
      name: "पूरा नाम",
      email: "ईमेल",
      card: "कार्ड नंबर",
      exp: "समाप्ति तिथि",
      cvc: "सुरक्षा कोड",
      captcha: "पुष्टि कोड"
    };

    const HOLD_MS = 120000;
    let deadline = Date.now() + HOLD_MS;
    let warned = false;
    let expired = false;
    let complete = false;
    let interval;

    function remainingSeconds() {
      return Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
    }

    function renderTimer() {
      if (complete) return;

      const seconds = remainingSeconds();
      const minutes = Math.floor(seconds / 60);
      const remainder = seconds % 60;
      $("clock").textContent =
        `${minutes}:${String(remainder).padStart(2, "0")}`;
      $("clock").setAttribute(
        "aria-label", `${minutes} मिनट ${remainder} सेकंड शेष`
      );

      if (seconds === 0 && !expired) {
        expired = true;
        $("hold-status").textContent = "";
        $("hold-alert").textContent =
          "होल्ड समाप्त हुआ। विवरण यहीं हैं; भुगतान नहीं हुआ है। " +
          "भुगतान से पहले फिर टिकट उपलब्धता जाँचें।";
        $("hold-action").textContent =
          "फिर टिकट उपलब्धता जाँचें — डेमो";
      } else if (seconds > 0 && seconds <= 30 && !warned) {
        warned = true;
        $("hold-status").textContent =
          "होल्ड समाप्त होने वाला है। 'होल्ड 2 मिनट बढ़ाएँ' दबाएँ।";
      }
    }

    function holdIsActive() {
      renderTimer();
      return !expired && Date.now() < deadline;
    }

    $("hold-action").addEventListener("click", () => {
      renderTimer();

      if (expired) {
        // Production: request a NEW hold, handle unavailable inventory,
        // and refresh authoritative price before allowing payment.
        deadline = Date.now() + HOLD_MS;
        expired = false;
        $("hold-status").textContent =
          "डेमो: टिकट उपलब्ध मानकर नया 2 मिनट का होल्ड शुरू हुआ।";
      } else {
        // Production: extend only after the server confirms the new deadline.
        deadline += HOLD_MS;
        $("hold-status").textContent =
          `होल्ड 2 मिनट बढ़ा। अब लगभग ${
            Math.ceil(remainingSeconds() / 60)
          } मिनट उपलब्ध हैं।`;
      }

      warned = false;
      $("hold-alert").textContent = "";
      $("payment-status").textContent = "";
      $("hold-action").textContent = "होल्ड 2 मिनट बढ़ाएँ";
      renderTimer();
    });

    interval = setInterval(renderTimer, 250);
    document.addEventListener("visibilitychange", renderTimer);
    window.addEventListener("pageshow", renderTimer);
    renderTimer();

    $("email").addEventListener("blur", () => {
      $("email").value = $("email").value.trim();
      const value = $("email").value;
      const at = value.lastIndexOf("@");
      const domain = value.slice(at + 1).toLowerCase();
      const suggestions = {
        "gmial.com": "gmail.com",
        "gamil.com": "gmail.com",
        "outlok.com": "outlook.com"
      };

      $("email-suggestion").textContent =
        at > 0 && suggestions[domain]
          ? `क्या आपका पता ${value.slice(0, at)}@${suggestions[domain]} है? ` +
            "जरूरत हो तो स्वयं बदलें; हमने पता नहीं बदला है।"
          : "";
    });

    function cardDigits() {
      return $("card").value.replace(/[ -]/g, "");
    }

    function passesLuhn(digits) {
      let sum = 0;
      let double = false;
      for (let i = digits.length - 1; i >= 0; i--) {
        let digit = Number(digits[i]);
        if (double) {
          digit *= 2;
          if (digit > 9) digit -= 9;
        }
        sum += digit;
        double = !double;
      }
      return !/^0+$/.test(digits) && sum % 10 === 0;
    }

    function validExpiry(value) {
      const match = value.trim().match(/^(\d{2})\s*\/?\s*(\d{2}|\d{4})$/);
      if (!match) return false;

      const month = Number(match[1]);
      const year = match[2].length === 2
        ? 2000 + Number(match[2])
        : Number(match[2]);

      if (month < 1 || month > 12) return false;
      const now = new Date();

      // Cards remain valid through their expiry month.
      return year > now.getFullYear() ||
        (year === now.getFullYear() && month >= now.getMonth() + 1);
    }

    function errorFor(id) {
      const value = $(id).value.trim();

      switch (id) {
        case "name":
          return value ? "" : "अपना पूरा नाम भरें।";
        case "email":
          if (!value) return "टिकट पाने के लिए ईमेल भरें।";
          return $("email").validity.typeMismatch
            ? "ईमेल का प्रारूप जाँचें, जैसे name@example.com।"
            : "";
        case "card": {
          const digits = cardDigits();
          return /^\d{12,19}$/.test(digits) && passesLuhn(digits)
            ? ""
            : "कार्ड नंबर जाँचें: 12–19 अंक; केवल spaces या hyphens अतिरिक्त रखें।";
        }
        case "exp":
          return validExpiry(value)
            ? ""
            : "मान्य, गैर-समाप्त महीना/वर्ष भरें; जैसे MM/YY या MMYY।";
        case "cvc":
          return /^\d{3,4}$/.test(value)
            ? ""
            : "कार्ड का 3 या 4 अंकों वाला सुरक्षा कोड भरें।";
        case "captcha":
          return value.toUpperCase() === "M7Q4"
            ? ""
            : "ऊपर दिया demo code M7Q4 भरें; copy/paste भी कर सकते हैं।";
        default:
          return "";
      }
    }

    function validate() {
      $("name").value = $("name").value.trim();
      $("email").value = $("email").value.trim();
      const list = $("error-list");
      list.replaceChildren();
      let count = 0;

      for (const id of fieldIds) {
        const message = errorFor(id);
        const input = $(id);
        const error = $(`${id}-error`);

        error.textContent = message;
        error.hidden = !message;

        if (message) {
          count++;
          input.setAttribute("aria-invalid", "true");

          const item = document.createElement("li");
          const link = document.createElement("a");
          link.href = `#${id}`;
          link.textContent = `${labels[id]}: ${message}`;
          link.addEventListener("click", event => {
            event.preventDefault();
            input.focus();
          });
          item.append(link);
          list.append(item);
        } else {
          input.removeAttribute("aria-invalid");
        }
      }

      $("errors").hidden = count === 0;
      if (count) $("errors").focus();
      return count === 0;
    }

    form.addEventListener("submit", event => {
      event.preventDefault();
      if (!validate()) return;

      // Use textContent, not HTML interpolation, for user-supplied values.
      $("review-name").textContent = $("name").value;
      $("review-email").textContent = $("email").value;
      $("review-phone").textContent = $("phone").value.trim() || "नहीं दिया";
      $("review-card").textContent = `अंतिम चार अंक: ${cardDigits().slice(-4)}`;
      $("review-news").textContent = $("news").checked
        ? "हाँ — स्वैच्छिक opt-in"
        : "नहीं";

      form.hidden = true;
      $("review").hidden = false;
      $("payment-status").textContent = "";
      $("review").focus();
    });

    $("edit").addEventListener("click", () => {
      $("review").hidden = true;
      form.hidden = false;
      $("email").focus();
    });

    $("pay").addEventListener("click", () => {
      if (complete) return;

      if (!holdIsActive()) {
        $("payment-status").textContent =
          "भुगतान नहीं हुआ। पहले ऊपर 'फिर टिकट उपलब्धता जाँचें' दबाएँ।";
        $("hold-action").focus();
        return;
      }

      // Demo completes synchronously. A real payment flow must recheck the
      // server hold/total, prevent duplicate charges, and handle declines,
      // pending results, authentication, network failures and recovery.
      complete = true;
      clearInterval(interval);

      $("success-email").textContent =
        `समीक्षा किया गया ईमेल: ${$("email").value}`;
      $("review").hidden = true;
      $("hold-panel").hidden = true;
      $("success").hidden = false;

      // Do not retain payment data after the demo transaction.
      $("card").value = "";
      $("exp").value = "";
      $("cvc").value = "";
      $("success").focus();
    });
  </script>
</body>
</html>
